def find_length(binary_string):
    def max_diff_subarray(arr):
        # Kadane's Algorithm for maximum sum subarray
        max_diff = float('-inf')
        current_diff = 0

        for value in arr:
            current_diff += value
            if current_diff > max_diff:
                max_diff = current_diff
            if current_diff < 0:
                current_diff = 0

        return max_diff

    # Transform the binary string into an array where 0 -> +1 and 1 -> -1
    transformed_array = [1 if char == '0' else -1 for char in binary_string]

    # Find the maximum difference using Kadane's Algorithm
    return max_diff_subarray(transformed_array)

# Example usage and test
assert find_length("11000010001") == 6
```

