def sequential_search(arr, element):
    """
    This function takes an array and an element, and returns a tuple:
    - The first value is a boolean indicating if the element is in the array.
    - The second value is the index of the element in the array, or -1 if not found.
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)

