def max_aggregate(data):
    # Dictionary to store the aggregate scores
    aggregate_scores = {}

    # Loop through the list of tuples
    for name, score in data:
        # Add the score to the corresponding name in the dictionary
        if name in aggregate_scores:
            aggregate_scores[name] += score
        else:
            aggregate_scores[name] = score

    # Find the maximum aggregate score and the corresponding name
    max_name = max(aggregate_scores, key=aggregate_scores.get)
    return (max_name, aggregate_scores[max_name])

