def count_Substrings(s):
    def digit_sum(substring):
        return sum(int(ch) for ch in substring)

    n = len(s)
    count = 0

    # Iterate through all substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            if digit_sum(substring) == len(substring):
                count += 1

    return count

