def tuple_to_dict(input_tuple):
    """
    Convert a tuple into a dictionary using adjacent elements as key-value pairs.

    Args:
    input_tuple (tuple): Tuple consisting of elements.

    Returns:
    dict: Dictionary with adjacent elements of the tuple as key-value pairs.
    """
    # Create the dictionary using slicing and pairing adjacent elements
    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple) - 1, 2)}

