def is_polite(num):
    # A number is polite if it is not a power of 2
    return (num & (num - 1)) != 0

def nth_polite_number(n):
    count = 0
    current = 1
    while True:
        if is_polite(current):
            count += 1
            if count == n:
                return current
        current += 1

# Example usage:
assert nth_polite_number(7) == 11
```

