def merge_dictionaries_three(dict1, dict2, dict3):
    # Merge dictionaries in order: dict1, dict2, dict3.
    # Later values overwrite earlier ones for duplicate keys.
    merged_dict = {}
    for d in [dict1, dict2, dict3]:
        merged_dict.update(d)
    return merged_dict

